name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
// Unset CI and GITHUB_ACTIONS so Droid doesn't enter single-turn/headless
// mode — it checks these vars and skips interactive input after the first turn.
//
// Pass the BYOK --model explicitly, exactly as RunPrompt does. Without it,
// the interactive TUI falls back to Factory-hosted models and validates
// FACTORY_API_KEY at startup, exiting with "FACTORY_API_KEY ... appears to be
// invalid" before the ">" prompt ever appears. The headless path proves the
// fix: it has FACTORY_API_KEY set too, yet works because --model selects the
// ANTHROPIC_API_KEY-backed custom model configured in ~/.factory/settings.json.
s, err := NewTmuxSession(name, dir, []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}, d.Binary(), "--model", defaultDroidModel)
